"""make_env and make_agent on the core.RunSettings samples, with recording doubles (PL-01 steps 2, 7)."""

import importlib.util
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Any

import pytest

from rllab.core import SOLO, ActionSpace, RunSettings, TeamSpec
from rllab.lab import build

pytestmark = pytest.mark.unit

CONTRACTS = Path(__file__).parents[2] / "contracts"
_spec = importlib.util.spec_from_file_location("contracts_codec", CONTRACTS / "codec.py")
assert _spec is not None
assert _spec.loader is not None
codec = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(codec)

COMPACT_TEAM = TeamSpec(n_agents=1, obs_shape=(11,), actions=ActionSpace("discrete", n=3))
CORRIDOR_TEAM = TeamSpec(n_agents=1, obs_shape=(10,), actions=ActionSpace("discrete", n=2))


def _settings(case: str) -> RunSettings:
    result: RunSettings = codec.sample("core.RunSettings", case, RunSettings)
    return result


class Recorder:
    """Stands in for a constructor: remembers its arguments, returns itself as the product."""

    def __init__(self, name: str) -> None:
        self.name = name
        self.calls: list[tuple[tuple[Any, ...], dict[str, Any]]] = []

    def __call__(self, *args: Any, **kwargs: Any) -> "Recorder":
        self.calls.append((args, kwargs))
        return self


@dataclass
class TeamsOnly:
    """An environment double holding only its teams."""

    teams: dict[str, TeamSpec]


@pytest.fixture
def recorders(monkeypatch: pytest.MonkeyPatch) -> dict[str, Recorder]:
    names = ("Snake", "Corridor", "TabularAgent", "DQNAgent", "RandomPlayer", "ScriptedPlayer")
    found = {name: Recorder(name) for name in names}
    for name, recorder in found.items():
        monkeypatch.setattr(build, name, recorder)
    return found


def test_snake_factory_builds_on_each_call_with_view_and_rewards(recorders):
    settings = _settings("dqn_compact")
    make = build.make_env(settings)
    assert recorders["Snake"].calls == []
    assert make() is recorders["Snake"]
    make()
    assert recorders["Snake"].calls == [((), {"view": "compact", "rewards": settings.rewards})] * 2
    assert recorders["Corridor"].calls == []


def test_snake_grid_view_is_passed_through(recorders):
    build.make_env(replace(_settings("dqn_compact"), view="grid"))()
    assert recorders["Snake"].calls[0][1]["view"] == "grid"


def test_corridor_factory_gets_the_rewards(recorders):
    settings = _settings("corridor_tabular")
    assert build.make_env(settings)() is recorders["Corridor"]
    assert recorders["Corridor"].calls == [((), {"rewards": settings.rewards})]
    assert recorders["Snake"].calls == []


@pytest.mark.parametrize("case", ["tank_rung3", "predprey_rung1"])
def test_environments_not_yet_built_are_refused(case):
    with pytest.raises(ValueError, match="env"):
        build.make_env(_settings(case))


def test_dqn_is_sized_from_the_team_with_no_ablation(recorders):
    settings = _settings("dqn_compact")
    agents = build.make_agent(settings, TeamsOnly({SOLO: COMPACT_TEAM}))
    assert agents == {SOLO: recorders["DQNAgent"]}
    assert recorders["DQNAgent"].calls == [
        (
            (COMPACT_TEAM, settings.params, settings.exploration),
            {"seed": settings.seed, "ablation": "none"},
        )
    ]


def test_dqn_gets_the_no_target_switch(recorders):
    settings = replace(_settings("no_target"), seed=7)
    build.make_agent(settings, TeamsOnly({SOLO: COMPACT_TEAM}))
    assert recorders["DQNAgent"].calls[0][1] == {"seed": 7, "ablation": "no_target"}


def test_tabular_is_sized_from_the_team_actions(recorders):
    settings = _settings("corridor_tabular")
    agents = build.make_agent(settings, TeamsOnly({SOLO: CORRIDOR_TEAM}))
    assert agents == {SOLO: recorders["TabularAgent"]}
    assert recorders["TabularAgent"].calls == [
        (
            (2, settings.params, settings.exploration),
            {"seed": settings.seed, "explore_enabled": True},
        )
    ]


def test_tabular_no_explore_turns_exploration_off(recorders):
    settings = replace(_settings("corridor_tabular"), ablation="no_explore")
    build.make_agent(settings, TeamsOnly({SOLO: CORRIDOR_TEAM}))
    assert recorders["TabularAgent"].calls[0][1]["explore_enabled"] is False


def test_baselines_are_built_for_the_one_team(recorders):
    random_settings = replace(_settings("dqn_compact"), agent="random", seed=3)
    assert build.make_agent(random_settings, TeamsOnly({SOLO: COMPACT_TEAM})) == {
        SOLO: recorders["RandomPlayer"]
    }
    assert recorders["RandomPlayer"].calls == [((3,), {"seed": 3})]
    scripted_settings = replace(_settings("dqn_compact"), agent="scripted")
    assert build.make_agent(scripted_settings, TeamsOnly({SOLO: COMPACT_TEAM})) == {
        SOLO: recorders["ScriptedPlayer"]
    }


def test_agents_not_built_from_settings_are_refused(recorders):
    settings = replace(_settings("dqn_compact"), agent="reference")
    with pytest.raises(ValueError, match="reference"):
        build.make_agent(settings, TeamsOnly({SOLO: COMPACT_TEAM}))

